.manualSavedCard {
  padding: 0 !important;
  border-radius: 14px !important;
  background: #ffffff !important;
}

/* 카드 상단 */
.manualSavedCardHead {
  margin: 0 !important;
  padding: 10px 11px !important;
  min-height: 52px !important;
}

.manualSavedCard[open] > .manualSavedCardHead {
  border-bottom: 1px solid #edf1f6 !important;
}

.manualSavedCardHead h3 {
  margin-top: 4px !important;
  font-size: 13px !important;
  line-height: 1.25 !important;
}

.manualSavedResult {
  gap: 5px !important;
}

.myTotalOdds {
  gap: 4px !important;
}

.myTotalOdds > strong {
  font-size: 12px !important;
}

/* 픽 목록 */
.manualSavedPicks {
  margin: 8px 9px 0 !important;
  gap: 4px !important;
}

.manualSavedPick {
  display: grid !important;
  grid-template-columns:
    minmax(0, 1fr)
    auto
    auto !important;

  gap: 4px 5px !important;

  padding: 6px 7px !important;

  border: 1px solid #edf1f6 !important;
  border-radius: 8px !important;

  background: #fbfcfe !important;
}

.manualSavedPick > b {
  min-width: 0 !important;

  font-size: 10px !important;
  line-height: 1.2 !important;

  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

.manualSavedPickOdds {
  font-size: 8px !important;
  padding: 3px 6px !important;
}

.myPickResultBadge {
  min-width: 0 !important;
  padding: 3px 6px !important;
  font-size: 8px !important;
}

/* 경기명은 픽 아래쪽 한 줄 */
.manualSavedPick > span:last-child {
  grid-column: 1 / -1 !important;

  margin-top: 0 !important;

  font-size: 8px !important;
  padding: 2px 6px !important;
}

/* 예상 반환 / 예상 손익 */
.manualSavedCalc {
  display: grid !important;
  grid-template-columns:
    repeat(2, minmax(0, 1fr)) !important;

  gap: 5px !important;

  margin: 7px 9px 0 !important;
}

.manualSavedCalc > span {
  padding: 7px 8px !important;
  border: 1px solid #edf1f6 !important;
  border-radius: 8px !important;
  background: #ffffff !important;

  font-size: 8px !important;
}

.manualSavedCalc > span > b {
  margin-left: 5px !important;
  font-size: 10px !important;
}

/* 베팅금액 관리 + 정산 영역 */
.myComboCompactSettlement {
  margin: 7px 9px 0 !important;
  border-radius: 9px !important;
  overflow: hidden !important;
  background: #f8fafc !important;
}

.myComboStakeManage {
  min-height: 38px !important;
  padding: 6px 7px !important;
}

.myComboStakeManage > span {
  gap: 6px !important;
  font-size: 8px !important;
}

.myComboStakeManage > span strong {
  font-size: 10px !important;
}

.myComboStakeManage > button {
  padding: 4px 8px !important;
  min-height: 26px !important;
  font-size: 8px !important;
  border-radius: 7px !important;
}

.myComboStakeEditField input {
  min-height: 27px !important;
  padding: 4px 7px !important;
  font-size: 10px !important;
}

/* 총배당 / 적중배당 / 반환 / 손익 */
.myComboResultStrip {
  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 4px !important;

  padding: 5px 6px 6px !important;
}

.myComboResultStrip > span {
  padding: 5px 6px !important;

  border: 1px solid #eef2f6 !important;
  border-radius: 7px !important;

  font-size: 7px !important;
}

.myComboResultStrip b {
  font-size: 9px !important;
}

/* 저장취소 */
.manualSavedCard > .myComboCancelButton {
  display: block !important;

  width: fit-content !important;
  min-width: 86px !important;

  margin:
    7px
    9px
    9px
    auto !important;

  padding: 5px 9px !important;

  border-radius: 7px !important;

  font-size: 8px !important;
}

/* PC 2열 간격도 살짝 압축 */
.manualSavedGrid {
  gap: 9px !important;
}

/* 모바일 */
@media (max-width: 900px) {
  .manualSavedGrid {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 560px) {
  .manualSavedPick {
    grid-template-columns:
      minmax(0,1fr)
      auto !important;
  }

  .manualSavedPickOdds {
    grid-column: 2 !important;
    grid-row: 1 !important;
  }

  .myPickResultBadge {
    grid-column: 2 !important;
    grid-row: 2 !important;
  }

  .manualSavedPick > span:last-child {
    grid-column: 1 !important;
    grid-row: 2 !important;
  }

  .myComboResultStrip {
    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;
  }
}

/* MY_COMBO_COLLAPSE_HEIGHT_FIX_V1 */

/* 같은 행의 펼친 카드 높이를 따라가지 않게 */
.manualSavedGrid {
  align-items: start !important;
  grid-auto-rows: auto !important;
}

/* 각 카드가 자기 내용 높이만 사용 */
.manualSavedCard {
  height: auto !important;
  min-height: 0 !important;
  align-self: start !important;
}

/* 접힌 카드는 헤더 높이까지만 */
.manualSavedCard:not([open]) {
  height: auto !important;
  min-height: 0 !important;
}

/* 접힌 상태에서 summary 외 영역이 높이에 영향 주지 않도록 */
.manualSavedCard:not([open]) > :not(summary) {
  display: none !important;
}


