@media (max-width: 760px) {

  /*
    기존 모바일 사이드바/하단메뉴에서
    모든 버튼 표시
  */
  .sidebar .mainNav button,
  .sidebar nav button {
    display: flex !important;
    visibility: visible !important;
    opacity: 1 !important;
  }

  /*
    5개 메뉴가 한 줄에 들어가도록
  */
  .sidebar .mainNav,
  .sidebar nav {
    grid-template-columns:
      repeat(
        5,
        minmax(0, 1fr)
      ) !important;

    gap: 4px !important;
  }

  .sidebar .mainNav button,
  .sidebar nav button {
    min-width: 0 !important;
    padding:
      8px
      3px !important;

    justify-content: center !important;

    font-size: 10px !important;
    line-height: 1.25 !important;
    white-space: nowrap !important;
  }

  /*
    혹시 예전 CSS에서 4번째 이후를
    숨기고 있던 규칙이 있어도 복구
  */
  .sidebar .mainNav button:nth-child(4),
  .sidebar .mainNav button:nth-child(5),
  .sidebar nav button:nth-child(4),
  .sidebar nav button:nth-child(5) {
    display: flex !important;
  }

  /*
    설정 화면 폭
  */
  .settingsPage {
    width: 100%;
    min-width: 0;
  }

  .settingsHero,
  .settingsCard,
  .settingsActions {
    width: 100%;
    min-width: 0;
  }
}


