   ========================================================== */

.profilePageV1{
  display:flex;
  flex-direction:column;
  gap:18px;
}

.profileHeroV1{
  min-height:210px;
  padding:28px 30px;
  border-radius:24px;
  background:
    radial-gradient(circle at 90% 0%,rgba(255,255,255,.08),transparent 34%),
    linear-gradient(135deg,#101d34,#162943);
  color:#fff;
  display:grid;
  grid-template-columns:minmax(330px,1fr) minmax(520px,1.25fr);
  gap:28px;
  align-items:center;
  box-shadow:0 14px 34px rgba(15,23,42,.13);
}

.profileIdentityV1{
  display:flex;
  align-items:center;
  gap:24px;
  min-width:0;
}

.profileJerseyV1{
  width:158px;
  height:150px;
  flex:0 0 158px;
  border-radius:18px;
  background:#fff;
  position:relative;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  overflow:hidden;
  box-shadow:
    0 12px 28px rgba(0,0,0,.22),
    inset 0 0 0 1px rgba(15,23,42,.08);
}

.profileJerseyV1:before,
.profileJerseyV1:after{
  content:"";
  position:absolute;
  top:20px;
  width:48px;
  height:1px;
  background:#d8dee8;
}

.profileJerseyV1:before{
  left:-4px;
  transform:rotate(-18deg);
}

.profileJerseyV1:after{
  right:-4px;
  transform:rotate(18deg);
}

.profileJerseyCollarV1{
  position:absolute;
  width:70px;
  height:35px;
  border:8px solid #d62532;
  border-top:0;
  border-radius:0 0 40px 40px;
  top:-2px;
}

.profileJerseyCollarV1:after{
  content:"";
  position:absolute;
  left:-4px;
  right:-4px;
  bottom:-12px;
  height:5px;
  border-radius:5px;
  background:#162943;
}

.profileJerseyV1 > span{
  margin-top:20px;
  color:#d62532;
  font-size:19px;
  font-weight:900;
  letter-spacing:.5px;
  max-width:130px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.profileJerseyV1 > strong{
  margin-top:-4px;
  color:#d62532;
  font-size:62px;
  line-height:1;
  font-weight:1000;
  letter-spacing:-5px;
  -webkit-text-stroke:2px #162943;
}

.profileIdentityTextV1{
  min-width:0;
}

.profileIdentityTextV1 > small,
.profileCollectionV1 small,
.profileActivityHeadV1 small{
  display:block;
  font-size:11px;
  font-weight:900;
  letter-spacing:1.5px;
  opacity:.62;
}

.profileIdentityTextV1 > span{
  display:block;
  margin-top:3px;
  font-size:12px;
  font-weight:900;
  letter-spacing:1px;
  color:#9fb4d1;
}

.profileIdentityTextV1 h1{
  margin:10px 0 5px;
  font-size:28px;
  line-height:1.15;
}

.profileIdentityTextV1 p{
  margin:0;
  color:#b9c7d9;
  font-size:13px;
}

.profileIdentityTextV1 button{
  margin-top:14px;
  padding:8px 13px;
  border:1px solid rgba(255,255,255,.2);
  border-radius:10px;
  background:rgba(255,255,255,.08);
  color:#fff;
  font-weight:800;
  cursor:pointer;
}

.profileStatsV1{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
}

.profileStatsV1 article{
  min-height:104px;
  padding:15px 14px;
  border:1px solid rgba(255,255,255,.1);
  border-radius:16px;
  background:rgba(255,255,255,.055);
  display:flex;
  flex-direction:column;
}

.profileStatsV1 article > span{
  color:#8197b6;
  font-size:10px;
  font-weight:900;
  letter-spacing:1px;
}

.profileStatsV1 article > small{
  margin-top:7px;
  color:#c2cedd;
  font-size:11px;
}

.profileStatsV1 article > strong{
  margin-top:auto;
  font-size:18px;
  color:#fff;
}

.profileStatsV1 strong.positive{
  color:#86efac;
}

.profileStatsV1 strong.negative{
  color:#fca5a5;
}

.profileCollectionV1,
.profileActivityV1{
  padding:22px 24px;
